/**
 * Round-3 review finding #3 (worst): titleAutoGenerated was being written
 * unconditionally at creation, so an upload named by the USER'S OWN FILE
 * ("Q3 board meeting.mp4") — and a Loom import whose title a human typed —
 * got flagged machine-derived and the AI overwrote the human's title. Before
 * that, the regex simply never matched such names and they survived.
 *
 * The decision now lives in ONE helper: titleOriginMetadata(humanChosenTitle)
 * marks ONLY the dated-template fallback case. A source scan enforces that no
 * creation site writes the raw literal (RED against the pre-fix sites).
 */
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { titleOriginMetadata } from "@/lib/title-origin";
import { titleFromFileName } from "@/lib/video-title";

describe("titleOriginMetadata", () => {
	it("a realistic human filename is the USER'S title — never marked machine-derived", () => {
		expect(
			titleOriginMetadata(titleFromFileName("Q3 board meeting.mp4")),
		).toEqual({});
		expect(titleOriginMetadata("Bitrix24 uchrashuv")).toEqual({});
	});

	it("only the dated-template fallback (no human title) is marked", () => {
		expect(titleOriginMetadata(titleFromFileName(undefined))).toEqual({
			titleAutoGenerated: true,
		});
		expect(titleOriginMetadata(null)).toEqual({ titleAutoGenerated: true });
		expect(titleOriginMetadata("   ")).toEqual({ titleAutoGenerated: true });
	});
});

describe("creation sites route the mark through the helper (no raw literal)", () => {
	const CREATION_FILES = [
		"../../actions/video/create-for-processing.ts",
		"../../actions/video/upload.ts",
		"../../actions/loom.ts",
		"../../app/api/desktop/[...route]/video.ts",
	];

	for (const rel of CREATION_FILES) {
		it(`${rel} never writes titleAutoGenerated: true directly`, () => {
			const src = readFileSync(
				fileURLToPath(new URL(rel, import.meta.url)),
				"utf8",
			);
			// The raw literal is how the human-filename bug shipped: an
			// unconditional mark at a creation site. All sites must go through
			// titleOriginMetadata(humanChosenTitle) so the human/machine decision
			// stays in one reviewed place.
			expect(src).not.toMatch(/titleAutoGenerated:\s*true/);
			expect(src).toMatch(/titleOriginMetadata\(/);
		});
	}
});
